// Some portions generated by Codex

// @ts-check
const fs = require('fs');
const path = require('path');

const { test, expect } = require('@playwright/test');
const {
    deleteRepository,
    serverBaseUrl,
    uniqueRepositoryId,
    workbenchBaseUrl
} = require('./workbench-test-helpers.js');

const SERVER_BASE_URL = serverBaseUrl();
const WORKBENCH_BASE_URL = workbenchBaseUrl();
const REPOSITORY_ID = uniqueRepositoryId('query-explanation-alignment');
const QUERY_URL = `${WORKBENCH_BASE_URL}/repositories/${REPOSITORY_ID}/query`;
const REPOSITORY_URL = `${SERVER_BASE_URL}/repositories/${REPOSITORY_ID}`;
const SCREENSHOT_DIRECTORY = path.resolve(__dirname, '../../output/playwright');

test.setTimeout(120000);

test.beforeAll(async ({ request }) => {
    const response = await request.put(REPOSITORY_URL, {
        headers: { 'Content-Type': 'text/turtle' },
        data: memoryRepositoryConfig(REPOSITORY_ID)
    });
    expect([200, 201, 204]).toContain(response.status());
    fs.mkdirSync(SCREENSHOT_DIRECTORY, { recursive: true });
});

test.afterAll(async ({ request }) => {
    await deleteRepository(request, SERVER_BASE_URL, REPOSITORY_ID);
});

test('keeps both comparison explanations aligned as editor heights change', async ({ page }) => {
    await page.setViewportSize({ width: 1440, height: 1100 });
    await page.goto(QUERY_URL);
    await page.locator('.CodeMirror').waitFor({ state: 'visible' });
    await setPrimaryQuery(page, shortQuery());
    await page.locator('#explain-trigger').click();
    await waitForExplanation(page, '#query-explanation');
    await page.locator('#compare-toggle').click();
    await expect(page.locator('#query-compare-pane')).toBeVisible();
    await expect(page.locator('.query-compare-pane .CodeMirror')).toHaveCount(2);
    await expect.poll(() => page.locator('#query-compare-layout').evaluate(element =>
        element.getAnimations().some(animation => animation.playState === 'running'))).toBe(false);

    await setQueries(page, shortQuery(), longQuery());
    await refreshAndWaitForExplanations(page);
    await assertExplanationAlignment(page, 'query-compare-explanation-right-taller-20260927.png');
    await assertOneSidedStaleSurfaceAlignment(page, 'compare');

    await setQueries(page, longQuery(), shortQuery());
    await refreshAndWaitForExplanations(page);
    await assertExplanationAlignment(page, 'query-compare-explanation-left-taller-20260927.png');
    await assertOneSidedStaleSurfaceAlignment(page, 'primary');

    await page.locator('#query-compare-close').click();
    await expect(page.locator('#query-compare-layout')).not.toHaveClass(/query-compare-layout--active/);
    await page.locator('#compare-toggle').click();
    await expect(page.locator('#query-compare-pane')).toBeVisible();
    // As after the first opening, measure once the panes have finished opening (Firefox was still animating them).
    await expect.poll(() => page.locator('#query-compare-layout').evaluate(element =>
        element.getAnimations({ subtree: true }).some(animation => animation.playState === 'running'))).toBe(false);
    await setQueries(page, shortQuery(), longQuery());
    await refreshAndWaitForExplanations(page);
    await assertExplanationAlignment(page, 'query-compare-explanation-reopened-20260927.png');
    await assertAsymmetricExplainFailureAlignment(page);

    await page.setViewportSize({ width: 390, height: 900 });
    const narrowGeometry = await page.evaluate(() => {
        const panes = Array.from(document.querySelectorAll('.query-compare-pane'));
        const bounds = panes.map(pane => pane.getBoundingClientRect());
        return {
            viewportWidth: window.innerWidth,
            documentWidth: document.documentElement.scrollWidth,
            paneTops: bounds.map(rect => rect.top),
            paneWidths: bounds.map(rect => rect.width)
        };
    });
    expect(narrowGeometry.documentWidth).toBeLessThanOrEqual(narrowGeometry.viewportWidth + 1);
    expect(narrowGeometry.paneTops[1]).toBeGreaterThan(narrowGeometry.paneTops[0]);
    expect(Math.abs(narrowGeometry.paneWidths[0] - narrowGeometry.paneWidths[1])).toBeLessThanOrEqual(1);
    await page.screenshot({
        path: path.join(SCREENSHOT_DIRECTORY, 'query-compare-explanation-narrow-20260927.png'),
        fullPage: true
    });

});

async function setQueries(page, left, right) {
    await page.evaluate(({ primary, compare }) => {
        const editors = document.querySelectorAll('.query-compare-pane .CodeMirror');
        editors[0].CodeMirror.setValue(primary);
        editors[1].CodeMirror.setValue(compare);
    }, { primary: left, compare: right });
}

async function setPrimaryQuery(page, query) {
    await page.locator('.CodeMirror').first().evaluate((element, value) => {
        element.CodeMirror.setValue(value);
    }, query);
}

async function waitForExplanation(page, selector) {
    await page.waitForFunction(explanationSelector => {
        const explanation = document.querySelector(explanationSelector);
        return explanation && explanation.textContent.trim().length > 0
            && explanation.textContent.indexOf('Loading explanation...') < 0;
    }, selector);
}

async function refreshAndWaitForExplanations(page) {
    await page.locator('#explain-trigger').click();
    await page.waitForFunction(() => {
        const panes = [
            { explanationId: 'query-explanation', rowId: 'query-explanation-row', overlayId: 'query-explanation-overlay' },
            {
                explanationId: 'query-explanation-compare',
                rowId: 'query-explanation-row-compare',
                overlayId: 'query-explanation-overlay-compare'
            }
        ];
        return panes.every(pane => {
            const explanation = document.getElementById(pane.explanationId);
            const row = document.getElementById(pane.rowId);
            const overlay = document.getElementById(pane.overlayId);
            return explanation && row && getComputedStyle(row).display !== 'none'
                && explanation.textContent.trim().length > 0
                && explanation.textContent.indexOf('Loading explanation...') < 0
                && overlay && !overlay.classList.contains('query-explanation-overlay--visible');
        });
    });
}

async function assertExplanationAlignment(page, screenshotName) {
    const geometry = await page.evaluate(() => {
        const primaryEditor = document.querySelector('#query-primary-pane .CodeMirror').getBoundingClientRect();
        const compareEditor = document.querySelector('#query-compare-pane .CodeMirror').getBoundingClientRect();
        const primaryExplanation = document.querySelector('#query-explanation-row').getBoundingClientRect();
        const compareExplanation = document.querySelector('#query-explanation-row-compare').getBoundingClientRect();
        // The explanation columns sit side by side in the output card below the editors (app-shell plan M3.3); each
        // column is headed by its own label.
        const primaryLabel = document.querySelector('#query-explanation-row .query-explanation-column__label').getBoundingClientRect();
        const compareLabel = document.querySelector('#query-explanation-row-compare .query-explanation-column__label').getBoundingClientRect();
        const primarySurface = document.querySelector('#query-explanation-row .query-explanation-surface').getBoundingClientRect();
        const compareSurface = document.querySelector('#query-explanation-row-compare .query-explanation-surface').getBoundingClientRect();
        const primaryPane = document.querySelector('#query-primary-pane').getBoundingClientRect();
        const comparePane = document.querySelector('#query-compare-pane').getBoundingClientRect();
        return {
            viewportWidth: window.innerWidth,
            documentWidth: document.documentElement.scrollWidth,
            editorHeights: [primaryEditor.height, compareEditor.height],
            editorTops: [primaryEditor.top, compareEditor.top],
            explanationTops: [primaryExplanation.top, compareExplanation.top],
            labelTops: [primaryLabel.top, compareLabel.top],
            surfaceBounds: [primarySurface, compareSurface].map((rect, index) => ({
                left: rect.left,
                right: rect.right,
                paneLeft: [primaryPane, comparePane][index].left,
                paneRight: [primaryPane, comparePane][index].right
            })),
            surfaceTops: [primarySurface.top, compareSurface.top]
        };
    });
    expect(Math.abs(geometry.editorHeights[0] - geometry.editorHeights[1])).toBeGreaterThan(120);
    console.log(`${screenshotName}: ${JSON.stringify(geometry)}`);
    await page.screenshot({
        path: path.join(SCREENSHOT_DIRECTORY, screenshotName),
        fullPage: true
    });
    expect(Math.abs(geometry.editorTops[0] - geometry.editorTops[1])).toBeLessThanOrEqual(1);
    expect(Math.abs(geometry.explanationTops[0] - geometry.explanationTops[1])).toBeLessThanOrEqual(1);
    expect(Math.abs(geometry.labelTops[0] - geometry.labelTops[1])).toBeLessThanOrEqual(1);
    expect(Math.abs(geometry.surfaceTops[0] - geometry.surfaceTops[1])).toBeLessThanOrEqual(1);
    expect(geometry.documentWidth).toBeLessThanOrEqual(geometry.viewportWidth + 1);
    for (const surface of geometry.surfaceBounds) {
        expect(surface.left).toBeGreaterThanOrEqual(surface.paneLeft - 1);
        expect(surface.right).toBeLessThanOrEqual(surface.paneRight + 1);
    }
}

async function assertOneSidedStaleSurfaceAlignment(page, pane) {
    const editorSelector = pane === 'primary'
        ? '#query-primary-pane .CodeMirror'
        : '#query-compare-pane .CodeMirror';
    const statusSelector = pane === 'primary'
        ? '#query-explanation-status'
        : '#query-explanation-status-compare';
    const changedQuery = longQuery().replace('urn:long:0', 'urn:long:changed');
    await page.locator(editorSelector).evaluate((element, query) => {
        element.CodeMirror.setValue(query);
    }, changedQuery);
    await expect.poll(() => page.locator(statusSelector).evaluate(element =>
        element.classList.contains('query-explanation-status--visible')
        && element.classList.contains('query-explanation-status--stale'))).toBe(true);

    const geometry = await page.evaluate(() => {
        const primarySurface = document.querySelector('#query-explanation-row .query-explanation-surface').getBoundingClientRect();
        const compareSurface = document.querySelector('#query-explanation-row-compare .query-explanation-surface').getBoundingClientRect();
        const statuses = Array.from(document.querySelectorAll('.query-explanation-status'));
        const visibleStatuses = statuses.filter(status => status.classList.contains('query-explanation-status--visible'));

        return {
            surfaceTops: [primarySurface.top, compareSurface.top],
            statusCount: visibleStatuses.length,
            statusHeight: visibleStatuses[0].getBoundingClientRect().height,
            statusText: visibleStatuses[0].textContent.trim()
        };
    });

    console.log(`one-sided ${pane} stale state: ${JSON.stringify(geometry)}`);
    expect(geometry.statusCount).toBe(1);
    expect(geometry.statusHeight).toBeGreaterThan(18);
    expect(geometry.statusText).toContain('stale');
    expect(Math.abs(geometry.surfaceTops[0] - geometry.surfaceTops[1])).toBeLessThanOrEqual(1);
}

async function assertAsymmetricExplainFailureAlignment(page) {
    await setQueries(page, longQuery(), 'SELECT * WHERE { invalid syntax');
    await refreshAndWaitForExplanations(page);
    await expect(page.locator('#query-explanation-status-compare'))
        .toHaveClass(/query-explanation-status--error/);

    const geometry = await page.evaluate(() => {
        const primaryRow = document.querySelector('#query-explanation-row').getBoundingClientRect();
        const compareRow = document.querySelector('#query-explanation-row-compare').getBoundingClientRect();
        const primarySurface = document.querySelector('#query-explanation-row .query-explanation-surface').getBoundingClientRect();
        const compareSurface = document.querySelector('#query-explanation-row-compare .query-explanation-surface').getBoundingClientRect();
        const compareStatus = document.getElementById('query-explanation-status-compare');
        const primaryStatus = document.getElementById('query-explanation-status');
        return {
            rowTops: [primaryRow.top, compareRow.top],
            surfaceTops: [primarySurface.top, compareSurface.top],
            statusCount: [primaryStatus, compareStatus]
                .filter(status => status.classList.contains('query-explanation-status--visible')).length,
            statusHeight: compareStatus.getBoundingClientRect().height,
            statusText: compareStatus.textContent.trim()
        };
    });

    console.log(`one-sided explain failure: ${JSON.stringify(geometry)}`);
    expect(geometry.statusCount).toBe(1);
    expect(geometry.statusHeight).toBeGreaterThan(18);
    expect(geometry.statusText.length).toBeGreaterThan(0);
    expect(Math.abs(geometry.rowTops[0] - geometry.rowTops[1])).toBeLessThanOrEqual(1);
    expect(Math.abs(geometry.surfaceTops[0] - geometry.surfaceTops[1])).toBeLessThanOrEqual(1);
}

function shortQuery() {
    return 'SELECT * WHERE { ?s <urn:short> ?o }';
}

function longQuery() {
    const patterns = Array.from({ length: 30 }, (_, index) =>
        `  ?s <urn:long:${index}> ?o${index} .`).join('\n');
    return `SELECT * WHERE {\n${patterns}\n}`;
}

function memoryRepositoryConfig(repositoryId) {
    return `@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#>.\n` +
        `@prefix config: <tag:rdf4j.org,2023:config/>.\n\n` +
        `[] a config:Repository ;\n` +
        `   config:rep.id "${repositoryId}" ;\n` +
        `   rdfs:label "Query explanation alignment test" ;\n` +
        `   config:rep.impl [\n` +
        `      config:rep.type "openrdf:SailRepository" ;\n` +
        `      config:sail.impl [\n` +
        `         config:sail.type "openrdf:MemoryStore"\n` +
        `      ]\n` +
        `   ].`;
}
